VLAN:makeProtocolLab({title:"VLAN — Segment a switched network",sub:"See how VLAN IDs separate broadcast domains.",experiment:"VLAN tagging & isolation",layer:2,ess:"VLANs logically segment Layer 2 networks. Access ports typically carry one VLAN; trunks carry multiple VLANs using 802.1Q tags. VLANs alone do not provide routing between segments.",nodes:[["💻","PC A","VLAN 10"],["🔀","Switch","802.1Q"],["💻","PC B","VLAN 20"]],steps:[["Access port","A PC sends an ordinary Ethernet frame into its switch access port. The switch associates the frame with the configured VLAN.",{Port:"Access",VLAN:"10",Frame:"Untagged ingress",BroadcastDomain:"VLAN 10"},[0,1]],["Switch learns","The switch learns source MAC addresses in a VLAN-specific forwarding table.",{Learning:"Source MAC",Table:"MAC + VLAN",Forwarding:"Within VLAN"},[1]],["Trunk carries VLANs","A trunk link can carry multiple VLANs. 802.1Q adds a VLAN tag for frames on the trunk (with exceptions such as native VLAN handling).",{Link:"Trunk",Tag:"802.1Q",VLANs:"10 · 20 · …"},[1,2]],["Isolation","Different VLANs are distinct Layer 2 broadcast domains. Communication between VLANs requires Layer 3 routing.",{VLAN10:"Separate broadcast domain",VLAN20:"Separate broadcast domain",InterVLAN:"Router / L3 switch"},[0,2]]],challenge:["What is needed for typical communication between different VLANs?",["Layer 3 routing","ARP alone across VLANs","A larger MAC address"],0,"Correct. VLANs separate Layer 2 domains; inter-VLAN communication needs routing."]}),
