BGP:makeProtocolLab({title:"BGP — Exchange routes between networks",sub:"Understand autonomous systems, path attributes and policy.",experiment:"BGP route selection",layer:3,ess:"BGP is the inter-domain routing protocol of the Internet. It exchanges reachability between autonomous systems and applies policy. AS_PATH helps prevent loops and influences route selection.",nodes:[["🌐","AS 64501","Your network"],["🌐","AS 64502","Transit"],["🌐","AS 64503","Destination"]],steps:[["Peer session","BGP peers establish TCP sessions, commonly port 179, and exchange capabilities and routing information.",{Protocol:"BGP-4",Transport:"TCP 179",Session:"Established",Peers:"eBGP / iBGP"},[0,1]],["Advertise prefix","A peer advertises a prefix with path attributes, such as AS_PATH and NEXT_HOP.",{Prefix:"203.0.113.0/24",AS_PATH:"64502 64503",NEXT_HOP:"Peer address",Attributes:"Policy-relevant"},[1,2]],["Evaluate policy","Routers evaluate local policy and attributes. Path selection is not simply shortest physical distance.",{Policy:"Local preference (example)",AS_PATH:"Path information",Decision:"Policy first matters"},[0,1]],["Install & forward","Selected routes may enter the routing table and be used for forwarding, subject to validity and best-path selection.",{Prefix:"203.0.113.0/24",Status:"Best path (example)",Scope:"Inter-domain"},[0]]],challenge:["BGP is primarily used for:",["Inter-domain routing between autonomous systems","Local MAC learning","DNS recursion"],0,"Correct. BGP exchanges routes between autonomous systems and applies routing policy."]}),
