// Normalize initial/reset state across every lab: no active packet or highlighted destination until Next step.
// DNS already includes an explicit idle step.
Object.keys(labs).forEach(key=>{
 const first=labs[key].steps[0];
 if(!first || !/^Ready\\b/i.test(first.title||"")){
  labs[key].steps.unshift({title:"Ready · Start the simulation",desc:"The simulation is idle. No packet or message has been sent yet. Press Next step to begin and follow the network flow.",fields:{Status:"Ready",Action:"No packet sent yet"},nodes:[],flow:[]});
 }
});
const layerNames=["Physical","Data Link","Network","Transport","Session","Presentation","Application"],layerUnits=["Bits","Frames","Packets","Segments","Sessions","Data","Requests"];
let labKey="DNS",step=0,auto=null,cache=false,udpLoss=false,udpReorder=false,arpCached=false,fault="0",isn=1000,sIsn=7000;
function $(id){return document.getElementById(id)}
function render(){renderLabStatic();renderStep();}
function renderLabStatic(){
 const L=labs[labKey]; if(!L)return;
 const put=(id,value)=>{const el=$(id);if(el)el.textContent=value;};
 const html=(id,value)=>{const el=$(id);if(el)el.innerHTML=value;};
 const bind=(id,handler)=>{const el=$(id);if(el)el.onclick=handler;};
 put("labTitle",L.title);put("labSub",L.sub);put("experimentTitle",L.experiment);put("essentials",L.ess);
 html("osi",layerNames.map((n,i)=>'<div class="layer '+(i+1===L.layer?'active':'')+'"><span>'+(i+1)+'. '+n+'</span><b>'+layerUnits[i]+'</b></div>').reverse().join(""));
 html("labControls",L.controls||"");
 const challenge=$("challenge");
 if(challenge&&L.challenge){
  challenge.innerHTML='<p class="story" style="min-height:auto">'+L.challenge.q+'</p>'+L.challenge.opts.map((o,i)=>'<button class="choice" data-choice="'+i+'">'+String.fromCharCode(65+i)+'. '+o+'</button>').join("");
  challenge.querySelectorAll("[data-choice]").forEach(b=>b.onclick=()=>{
   const ok=+b.dataset.choice===L.challenge.a;
   challenge.querySelectorAll("button").forEach(x=>x.classList.remove("good","bad"));
   b.classList.add(ok?"good":"bad");put("feedback",ok?L.challenge.why:"Not quite — revisit the steps, then try again.");
  });
 }
 html("faultControl",'<div class="field"><label>Simulate a condition</label><select id="faultSelect">'+(L.faults||[]).map((x,i)=>'<option value="'+i+'">'+x+'</option>').join("")+'</select></div>');
 const fs=$("faultSelect");if(fs){fs.value=String(fault);fs.onchange=e=>{fault=e.target.value;arpCached=false;render();};}
 bind("next",()=>{step=Math.min(labs[labKey].steps.length-1,step+1);renderStep();});
 bind("prev",()=>{step=Math.max(0,step-1);renderStep();});
 bind("reset",reset);bind("play",toggleAuto);
 try{bindControls();}catch(err){console.warn("Packet City control binding skipped:",err);}
 try{faultExplain();}catch(err){console.warn("Packet City fault explanation skipped:",err);}
}
function renderStep(){
 const L=labs[labKey]; if(!L||!Array.isArray(L.steps)||!L.steps.length)return;
 let S=L.steps[Math.min(step,L.steps.length-1)];
 if(labKey==="ARP"&&fault==="1"&&step>=2){
  S=JSON.parse(JSON.stringify(S));
  if(step===2){S.title="3 · No ARP reply";S.desc="Host B is offline. No device responds to the broadcast ARP request, so the sender cannot learn the target MAC address.";S.fields={Opcode:"1 — Request (broadcast)",TargetIP:"192.168.1.20",Result:"No reply · target offline",Status:"Waiting / timeout"};S.nodes=[0,1,3];S.wire=1;}
  else{S.title="4 · Resolution failed";S.desc="The ARP request timed out without a reply. The IP-to-MAC mapping is not cached, and traffic to this neighbor cannot be delivered on the LAN.";S.fields={Mapping:"192.168.1.20 → UNKNOWN",Status:"Not cached",Result:"ARP resolution failed"};S.nodes=[0];S.wire=0;}
 }
 const put=(id,value)=>{const el=$(id);if(el)el.textContent=value;};
 const html=(id,value)=>{const el=$(id);if(el)el.innerHTML=value;};
 put("stepHint","STEP "+(step+1)+" / "+L.steps.length);
 put("stepText",S.title);
 html("story","<h3>"+S.title+"</h3>"+(S.desc||""));
 html("packetFields",Object.entries(S.fields||{}).map(([k,v])=>'<div class="kv"><span>'+k+'</span><span>'+v+'</span></div>').join(""));
 put("raw","SIMULATED "+labKey+" MESSAGE\n"+Object.entries(S.fields||{}).map(([k,v])=>k.padEnd(18)+" "+v).join("\n"));
 html("visual",diagram(L,S));
 put("feedback","");
}
function diagram(L,S){
 let arr=L.diagram;
 let p=arr.length===2?[15,85]:arr.length===3?[15,50,85]:arr.length===4?[12,38,64,88]:[10,30,50,70,90];
 // Route strictly follows the current step's declared node sequence.
 // Never inject lab-specific node sequences here: those stale overrides
 // were the source of wrong arrows/highlights across labs.
 // On reset/start, keep every lab visually idle. Packet motion and node
 // highlighting begin only after the learner advances from the first step.
 let path=step===0?[]:(S.flow||S.nodes||[]).filter(i=>Number.isInteger(i)&&i>=0&&i<arr.length);
 let from=path.length>=2?path[path.length-2]:-1;
 let dest=path.length>=2?path[path.length-1]:(path.length===1?path[0]:-1);
 let nodes=arr.map((q,i)=>'<div class="node '+(i===dest?'highlight':'')+(labKey==='ARP'&&fault==='1'&&i===2?' offline':'')+'" style="left:'+p[i]+'%;top:50%"><div class="emoji">'+q[0]+'</div><b>'+q[1]+'</b><small>'+q[2]+(labKey==='ARP'&&fault==='1'&&i===2?' · OFFLINE':'')+'</small></div>').join('');
 let base='<svg viewBox="0 0 1000 300" preserveAspectRatio="none">';
 for(let i=0;i<arr.length-1;i++){let x1=p[i]*10,x2=p[i+1]*10;base+='<line x1="'+x1+'" y1="150" x2="'+x2+'" y2="150" stroke="#304968" stroke-width="2"/>';}
 let activeArrow='';
 if(from>=0&&dest>=0&&from!==dest){
   let x1=p[from]*10,x2=p[dest]*10,dir=x2>x1?1:-1,offset=70,edge1=x1+dir*offset,edge2=x2-dir*offset;
   let travel='M '+edge1+' 150 L '+edge2+' 150';
   activeArrow='<g><path d="M -7 -5 L 7 0 L -7 5 Z" fill="#5bd9ed"><animateMotion dur=".65s" begin="0s" fill="freeze" rotate="auto" path="'+travel+'"/></path></g>';
 }
 return base+activeArrow+'</svg>'+nodes
}
function faultExplain(){let L=labs[labKey],txt=L.faults[Number(fault)]||L.faults[0]||"Normal";$("faultText").textContent="Scenario: "+txt+" · simulation behaviour is modified where supported.";if(labKey==="ARP"&&fault==="1")$("faultText").textContent="Target offline: ARP requests receive no reply; steps 3–4 show timeout and failed resolution.";if(labKey==="ARP"&&fault==="2")$("faultText").textContent="Cache hit: the known MAC is used without a broadcast request."; }
function bindControls(){if(labKey==="DNS"){ $("lookup").onclick=()=>{cache=false;step=0;render();$("dnsCache").textContent="Lookup started: "+$("hostname").value+" · cache miss";};$("clearCache").onclick=()=>{cache=false;$("dnsCache").textContent="Cache cleared. Next lookup will require recursive resolution.";};}
if(labKey==="TCP"){$("applySeq").onclick=()=>{isn=Number($("isn").value);sIsn=Number($("serverIsn").value);labs.TCP.steps[0].fields.Sequence=String(isn);labs.TCP.steps[1].fields.Acknowledgment=String(isn+1);labs.TCP.steps[1].fields.Sequence=String(sIsn);labs.TCP.steps[2].fields.Acknowledgment=String(sIsn+1);labs.TCP.steps[2].fields.Sequence=String(isn+1);render();$("tcpNote").textContent="Sequence values updated throughout the handshake.";};$("dropSynack").onclick=()=>{$("tcpNote").textContent="SYN-ACK dropped: client cannot complete handshake; it may retry the SYN.";};}
if(labKey==="UDP"){$("sendDatagrams").onclick=()=>{$("udpResults").textContent=udpLoss?"Sent 1, 2, 4, 5 · datagram #3 lost. UDP itself does not retry.":"Sent 1, 2, 3, 4, 5 · delivery depends on simulated network.";};$("shuffle").onclick=()=>{$("udpResults").textContent="Receiver observed: 2, 1, 4, 3, 5 · ordering is not guaranteed.";udpReorder=true;};$("lose").onclick=()=>{udpLoss=!udpLoss;$("udpResults").textContent="Packet loss "+(udpLoss?"enabled":"disabled")+" · press Send 5 datagrams to test.";};}
if(labKey==="ARP"){$("arpRequest").onclick=()=>{if(fault==="1"){$("arpCache").textContent="ARP request broadcast sent · no reply from 192.168.1.20 · resolution timed out";arpCached=false;}else if(fault==="2"){$("arpCache").textContent="Cache hit: 192.168.1.20 → 02:00:00:00:00:20 · no broadcast needed";arpCached=true;}else{$("arpCache").textContent=arpCached?"Cache hit: 192.168.1.20 → 02:00:00:00:00:20":"Broadcast request ff:ff:ff:ff:ff:ff → reply 02:00:00:00:00:20 · mapping learned";arpCached=true;}};$("arpClear").onclick=()=>{arpCached=false;$("arpCache").textContent="Cache cleared · 192.168.1.20 unknown";};}
if(labKey==="IP"){$("routeLookup").onclick=()=>{$("routeNote").textContent="Destination "+$("destIP").value+" matches 203.0.113.0/24; selected route (longest prefix match), next hop 10.0.0.2. Try 203.0.113.9.";};}
if(labKey==="TLS"){$("tlsValidate").onclick=()=>{$("tlsNote").textContent=fault==="1"?"Hostname mismatch: certificate identity does not match "+$("tlsHost").value:fault==="2"?"Certificate expired: validation fails.":"Simulated validation: trust chain, hostname and validity checked for "+$("tlsHost").value+".";};}
if(labKey==="HTTP"){$("buildRequest").onclick=()=>{$("httpPreview").textContent=$("method").value+" "+$("path").value+" HTTP/1.1\nHost: "+$("httpHost").value+"\nAccept: text/html\nUser-Agent: Packet City\n\n"+($("method").value==="POST"?"<simulated request body>":"");};}}
function reset(){clearInterval(auto);auto=null;step=0;fault="0";cache=false;udpLoss=false;udpReorder=false;arpCached=false;isn=1000;sIsn=7000;render()}
function toggleAuto(){if(auto){clearInterval(auto);auto=null;$("play").textContent="▶ Auto-play";return}$("play").textContent="❚❚ Pause";auto=setInterval(()=>{if(step>=labs[labKey].steps.length-1){clearInterval(auto);auto=null;$("play").textContent="▶ Auto-play";return}step++;renderStep();$("play").textContent="❚❚ Pause";},1200)}
document.querySelectorAll("[data-lab]").forEach(b=>b.onclick=()=>{labKey=b.dataset.lab;step=0;fault="0";document.querySelectorAll("[data-lab]").forEach(x=>x.classList.toggle("active",x===b));render()});
$("reset").onclick=reset;render();window.addEventListener('message',e=>{if(e.source!==document.getElementById('packetCityTutorFrame')?.contentWindow)return;const d=e.data;if(!d||d.type!=='packetcity-command')return;let result;try{const api=window.PacketCityAPI;if(!api)throw Error('Simulator API unavailable');switch(d.action){case'getState':result=api.getState();break;case'navigateLab':result=api.navigateLab(d.args?.lab);break;case'next':result=api.next();break;case'previous':result=api.previous();break;case'reset':result=api.reset();break;case'setFault':result=api.setFault(d.args?.index);break;default:throw Error('Unknown command')}e.source.postMessage({type:'packetcity-command-result',id:d.id,result},'*')}catch(err){e.source.postMessage({type:'packetcity-command-result',id:d.id,error:err.message},'*')}});window.PacketCityAPI={getState:()=>({lab:labKey,step:step+1,totalSteps:labs[labKey].steps.length,stepTitle:labs[labKey].steps[Math.min(step,labs[labKey].steps.length-1)].title,fault:labs[labKey].faults[Number(fault)]||"Normal",faultIndex:Number(fault),faultOptions:labs[labKey].faults.map((label,index)=>({index,label}))}),navigateLab:name=>{let key=Object.keys(labs).find(k=>k.toLowerCase()===String(name).toLowerCase());if(!key)return {ok:false,error:"Unknown lab. Available: "+Object.keys(labs).join(", ")};labKey=key;step=0;fault="0";document.querySelectorAll("[data-lab]").forEach(b=>b.classList.toggle("active",b.dataset.lab===key));render();return {ok:true,state:window.PacketCityAPI.getState()}},next:()=>{step=Math.min(labs[labKey].steps.length-1,step+1);render();return {ok:true,state:window.PacketCityAPI.getState()}},previous:()=>{step=Math.max(0,step-1);render();return {ok:true,state:window.PacketCityAPI.getState()}},reset:()=>{reset();return {ok:true,state:window.PacketCityAPI.getState()}},setFault:idx=>{let n=Number(idx);if(!Number.isInteger(n)||n<0||n>=labs[labKey].faults.length)return {ok:false,error:"Invalid fault option",options:labs[labKey].faults};fault=String(n);arpCached=false;render();return {ok:true,state:window.PacketCityAPI.getState()}}};
